def tier_assignment(revenue):
    if revenue >= quantiles[2]:
        return 'Top 20%'
    elif revenue >= quantiles[1]:
        return 'Top 30%'
    elif revenue >= quantiles[0]:
        return 'Top 50%'
    else:
        return 'Below Top 50%'

df['tier'] = df['total_revenue'].apply(tier_assignment)
